// Package client is a reusable Crow HTTP client. It is used by apps/crowctl
// and is safe to use from tests (point it at an httptest.Server via
// WithHTTPClient or a localhost baseURL).
package client

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"

	"github.com/immuta/operations/services/crow/pkg/api"
)

type Client struct {
	httpClient *http.Client
	baseURL    string
}

type Option func(*Client)

// WithHTTPClient overrides the default *http.Client (useful for tests and
// for callers that want custom timeouts or transport).
func WithHTTPClient(h *http.Client) Option {
	return func(c *Client) { c.httpClient = h }
}

// New constructs a Client pointed at baseURL (e.g. "https://crow.infrastructure.immuta.io").
// baseURL must not end in "/".
func New(baseURL string, opts ...Option) *Client {
	c := &Client{baseURL: baseURL, httpClient: http.DefaultClient}
	for _, opt := range opts {
		opt(c)
	}
	return c
}

// Typed errors consumers can match with errors.Is.
var (
	ErrAlreadyExists = errors.New("module version already exists")
	ErrNotFound      = errors.New("module version not found")
)

// Upload PUTs the given gzipped-tar body for the module version. It returns
// ErrAlreadyExists on HTTP 409, nil on 201, and a generic error otherwise.
func (c *Client) Upload(ctx context.Context, m api.Module, body io.Reader) error {
	if err := m.Validate(); err != nil {
		return err
	}
	if err := api.ValidateVersion(m.Version); err != nil {
		return err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, c.baseURL+m.UploadPath(), body)
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/octet-stream")
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	switch resp.StatusCode {
	case http.StatusCreated:
		return nil
	case http.StatusConflict:
		return ErrAlreadyExists
	default:
		return fmt.Errorf("unexpected status %d uploading %s", resp.StatusCode, m.UploadPath())
	}
}

// Exists returns (true, nil) on 200 or 204, (false, nil) on 404, and an
// error for any other status.
func (c *Client) Exists(ctx context.Context, m api.Module) (bool, error) {
	if err := m.Validate(); err != nil {
		return false, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodHead, c.baseURL+m.DownloadPath(), nil)
	if err != nil {
		return false, err
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return false, err
	}
	defer resp.Body.Close()
	switch resp.StatusCode {
	case http.StatusOK, http.StatusNoContent:
		return true, nil
	case http.StatusNotFound:
		return false, nil
	default:
		return false, fmt.Errorf("unexpected status %d checking %s", resp.StatusCode, m.DownloadPath())
	}
}

// ListVersions returns the module's version list in server order.
// Returns ErrNotFound when the module has no published versions.
func (c *Client) ListVersions(ctx context.Context, id api.ModuleIdentifier) ([]string, error) {
	if err := id.Validate(); err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+id.VersionsPath(), nil)
	if err != nil {
		return nil, err
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	switch resp.StatusCode {
	case http.StatusOK:
		var body api.ListVersionsResponse
		if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
			return nil, fmt.Errorf("decoding response: %w", err)
		}
		if len(body.Modules) == 0 {
			return nil, ErrNotFound
		}
		out := make([]string, len(body.Modules[0].Versions))
		for i, v := range body.Modules[0].Versions {
			out[i] = v.Version
		}
		return out, nil
	case http.StatusNotFound:
		return nil, ErrNotFound
	default:
		return nil, fmt.Errorf("unexpected status %d listing %s", resp.StatusCode, id.VersionsPath())
	}
}

