// Package api declares the Crow HTTP wire protocol: request/response types
// and segment/path helpers. Both the Crow server and its clients import this
// package so they cannot drift on what a valid module path or response shape
// looks like.
package api

type ModuleIdentifier struct {
	Namespace string
	Name      string
	Provider  string
}

type Module struct {
	ModuleIdentifier
	Version string
}

type VersionEntry struct {
	Version string `json:"version"`
}

type ModuleVersions struct {
	Versions []VersionEntry `json:"versions"`
}

type ListVersionsResponse struct {
	Modules []ModuleVersions `json:"modules"`
}

type ErrorResponse struct {
	Error string `json:"error"`
}

// ServiceDiscoveryResponse is the body of /.well-known/terraform.json. The
// "modules.v1" key is dictated by HashiCorp's Terraform service discovery
// protocol and cannot be renamed to camelCase.
// See https://developer.hashicorp.com/terraform/internals/remote-service-discovery
type ServiceDiscoveryResponse struct {
	ModulesV1 string `json:"modules.v1"` //nolint:tagliatelle // external wire format
}

