package api

import (
	"fmt"
	"regexp"
	"strings"
)

// segmentRegex matches a single path segment: starts with alphanumeric,
// followed by alphanumeric, dots, underscores, or hyphens. It is the single
// source of truth for segment validation — the Crow server and its clients
// both import this package so they cannot drift.
var segmentRegex = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]*$`)

// versionSemverRegex is the SemVer 2.0.0 grammar from semver.org, minus the
// build metadata suffix. Two intentional deviations from the spec:
//   - No leading 'v' allowed. Terraform's native module loader strips the
//     prefix when building download URLs (per hashicorp/go-version
//     normalization), while terragrunt's tfr:// passes the version through
//     verbatim. A v-prefixed version uploaded today would resolve via
//     terragrunt and 404 via terraform — failing fast on upload prevents
//     the divergence.
//   - No '+build.metadata' suffix allowed. segmentRegex above doesn't
//     permit '+', so a build-tagged version couldn't be served from the
//     URL even if we accepted it on upload.
var versionSemverRegex = regexp.MustCompile(`^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?$`)

type InvalidSegmentError struct {
	Segment string
}

func (e InvalidSegmentError) Error() string {
	return fmt.Sprintf("invalid segment %q: must match %s", e.Segment, segmentRegex)
}

// InvalidVersionError is returned when a version string is not valid SemVer
// 2.0.0 (no leading 'v', no '+build' metadata).
type InvalidVersionError struct {
	Version string
}

func (e InvalidVersionError) Error() string {
	return fmt.Sprintf("invalid version %q: expected bare SemVer 2.0.0 (e.g. \"1.2.3\", \"1.2.3-rc.1\") per https://semver.org", e.Version)
}

// ValidateSegments returns an InvalidSegmentError for the first segment that
// fails the regex. An empty slice passes.
func ValidateSegments(segments []string) error {
	for _, s := range segments {
		if !segmentRegex.MatchString(s) {
			return InvalidSegmentError{Segment: s}
		}
	}
	return nil
}

// ValidateVersion enforces SemVer 2.0.0 on a module version string. It is
// applied at upload boundaries (server handler + client) so non-semver
// versions can't enter storage. Download/list paths intentionally don't
// call this so that any v-prefixed versions still in S3 from before the
// guard remain reachable.
func ValidateVersion(version string) error {
	if !versionSemverRegex.MatchString(version) {
		return InvalidVersionError{Version: version}
	}
	return nil
}

func (id ModuleIdentifier) Validate() error {
	return ValidateSegments([]string{id.Namespace, id.Name, id.Provider})
}

func (id ModuleIdentifier) VersionsPath() string {
	return "/v1/modules/" + strings.Join([]string{id.Namespace, id.Name, id.Provider}, "/") + "/versions"
}

func (m Module) Validate() error {
	return ValidateSegments([]string{m.Namespace, m.Name, m.Provider, m.Version})
}

func (m Module) UploadPath() string {
	return "/v1/modules/" + strings.Join([]string{m.Namespace, m.Name, m.Provider, m.Version}, "/")
}

func (m Module) DownloadPath() string {
	return m.UploadPath() + "/download"
}

package archive

import (
	"archive/tar"
	"compress/gzip"
	"errors"
	"io"
	"os"
)

// CreateArchive Create new Writers for gzip and tar
// These writers are chained. Writing to the tar writer will
// write to the gzip writer which in turn will write to
// the "buf" writer
func CreateArchive(files []string, buf io.Writer, preserveDirs bool) error {
	if buf == nil {
		return errors.New("cannot create archive with nil buffer")
	}

	gw := gzip.NewWriter(buf)
	defer func() {
		_ = gw.Close()
	}()

	tw := tar.NewWriter(gw)
	defer func() {
		_ = tw.Close()
	}()

	// Iterate over files and add them to the tar archive
	for _, file := range files {
		err := addToArchive(tw, file, preserveDirs)
		if err != nil {
			return err
		}
	}

	return nil
}

// addToArchive adds a specified file to the archive using the provided tar.Writer.
func addToArchive(tw *tar.Writer, filename string, preserveDirs bool) error {
	// Open the file which will be written into the archive
	file, err := os.Open(filename)
	if err != nil {
		return err
	}
	defer func() {
		_ = file.Close()
	}()

	// Get FileInfo about our file providing file size, mode, etc.
	info, err := file.Stat()
	if err != nil {
		return err
	}

	// Create a tar Header from the FileInfo data
	header, err := tar.FileInfoHeader(info, info.Name())
	if err != nil {
		return err
	}

	if preserveDirs {
		// Use full path as name (FileInfoHeader only takes the basename)
		// If we don't do this the directory structure would
		// not be preserved
		// https://golang.org/src/archive/tar/common.go?#L626
		header.Name = filename
	}

	// Write file header to the tar archive
	err = tw.WriteHeader(header)
	if err != nil {
		return err
	}

	// Copy file content to tar archive
	_, err = io.Copy(tw, file)
	if err != nil {
		return err
	}

	return nil
}

