// Run launches the interactive picker → browser flow. The browser step
// requires extracting the fetched tarballs and producing a diff.Result,
// which the caller injects via the BuildBrowser callback so this package
// stays free of archive/diff dependencies at compile time.
func Run(ctx context.Context, cli *client.Client, reg *registry.Registry, build BuildBrowser) error {
