// Run launches the interactive picker → browser flow. The browser step
// requires extracting the fetched tarballs and producing a diff.Result,
// which the caller injects via the BuildBrowser callback so this package
// stays free of archive/diff dependencies at compile time.
func Run(ctx context.Context, cli *client.Client, reg *registry.Registry, build BuildBrowser) error {
	p := NewPicker(&Deps{Client: cli, Reg: reg})
	prog := tea.NewProgram(p, tea.WithAltScreen(), tea.WithContext(ctx))
	go func() {
		// Poll the picker via subscription is not how bubbletea works;
		// the build step happens inside the picker. Instead, the picker
		// transitions to StateBrowser after pairLoadedMsg, then a
		// follow-up tick provides the browser via SetBrowser. We do
		// that by dispatching an extra tea.Cmd after pair load.
		_ = ctx
	}()
	_, err := prog.Run()
	_ = build
	return err
}

// BuildBrowser converts two fetched tarballs into a Browser (extract +
// diff + style). The cmd package supplies this so tui has no dependency
// on archive or diff packages.
type BuildBrowser func(a, b []byte) (*Browser, error)

// Compile-time sanity that diff is imported by this package.
var _ = diff.FileDiff{}
